// Package srp implements the client side of AWS Cognito's SRP-6a variant
// (USER_SRP_AUTH / PASSWORD_VERIFIER). It is a port of pycognito's aws_srp
// and is checked against vectors generated by pycognito.
//
// The package also contains the matching server-side math (Verifier,
// ServerB, ServerKey) so the fake Cognito in internal/testutil can run a
// real SRP exchange.
package srp

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"math/big"
	"strings"
	"time"
)

// NHex is the RFC 5054 3072-bit group prime used by Cognito.
const NHex = ""

// GHex is the group generator.
const GHex = "2"

const infoBits = "Caldera Derived Key"

// TimestampLayout is the timestamp format Cognito expects in the
// PASSWORD_VERIFIER response (day of month without zero padding).
const TimestampLayout = "Mon Jan 2 15:04:05 UTC 2006"

var (
	bigN = mustHex(NHex)
	bigG = mustHex(GHex)
	bigK = mustHex(hexHash("00" + NHex + "0" + GHex))
)

func mustHex(s string) *big.Int {
	n, ok := new(big.Int).SetString(s, 16)
	if !ok {
		panic("srp: bad hex constant")
	}
	return n
}

// hashHex returns the zero-padded lower-case hex SHA-256 of b.
func hashHex(b []byte) string {
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// hexHash hashes the bytes represented by a hex string.
func hexHash(h string) string {
	b, err := hex.DecodeString(h)
	if err != nil {
		panic("srp: hexHash on invalid hex: " + err.Error())
	}
	return hashHex(b)
}

// PadHex mirrors pycognito's pad_hex: odd-length strings gain a leading
// "0"; strings whose first nibble has the high bit set gain "00", so the
// value is never read back as negative.
func PadHex(h string) string {
	if len(h)%2 == 1 {
		return "0" + h
	}
	if len(h) > 0 && strings.ContainsRune("89ABCDEFabcdef", rune(h[0])) {
		return "00" + h
	}
	return h
}

func padInt(n *big.Int) string { return PadHex(n.Text(16)) }

func computeHKDF(ikm, salt []byte) []byte {
	m := hmac.New(sha256.New, salt)
	m.Write(ikm)
	prk := m.Sum(nil)
	m = hmac.New(sha256.New, prk)
	m.Write([]byte(infoBits))
	m.Write([]byte{1})
	return m.Sum(nil)[:16]
}

func calculateU(a, b *big.Int) *big.Int {
	return mustHex(hexHash(padInt(a) + padInt(b)))
}

// poolName returns the part of a pool ID after the underscore
// ("us-west-2_abc" -> "abc").
func poolName(poolID string) string {
	if i := strings.IndexByte(poolID, '_'); i >= 0 {
		return poolID[i+1:]
	}
	return poolID
}

func calculateX(poolID, userID, password, saltHex string) *big.Int {
	up := hashHex([]byte(poolName(poolID) + userID + ":" + password))
	return mustHex(hexHash(PadHex(saltHex) + up))
}

// Client holds the ephemeral state of one SRP login.
type Client struct {
	PoolID   string
	Password string
	a        *big.Int
	A        *big.Int
}

// NewClient creates a client with a random private value.
func NewClient(poolID, password string) (*Client, error) {
	buf := make([]byte, 128)
	if _, err := rand.Read(buf); err != nil {
		return nil, fmt.Errorf("srp: random: %w", err)
	}
	return newClientWithA(poolID, password, new(big.Int).SetBytes(buf))
}

// NewClientWithPrivate creates a client with a fixed private value a.
// Intended for tests only.
func NewClientWithPrivate(poolID, password string, a *big.Int) (*Client, error) {
	return newClientWithA(poolID, password, a)
}

func newClientWithA(poolID, password string, a *big.Int) (*Client, error) {
	a = new(big.Int).Mod(a, bigN)
	A := new(big.Int).Exp(bigG, a, bigN)
	if new(big.Int).Mod(A, bigN).Sign() == 0 {
		return nil, errors.New("srp: safety check for A failed")
	}
	return &Client{PoolID: poolID, Password: password, a: a, A: A}, nil
}

// AHex returns SRP_A for InitiateAuth.
func (c *Client) AHex() string { return c.A.Text(16) }

// Challenge carries the PASSWORD_VERIFIER challenge parameters.
type Challenge struct {
	UserIDForSRP string // USER_ID_FOR_SRP
	Username     string // USERNAME (falls back to UserIDForSRP)
	SaltHex      string // SALT
	BHex         string // SRP_B
	SecretBlock  string // SECRET_BLOCK (base64)
}

// Response returns the ChallengeResponses map for RespondToAuthChallenge.
func (c *Client) Response(ch Challenge, now time.Time) (map[string]string, error) {
	B, ok := new(big.Int).SetString(ch.BHex, 16)
	if !ok {
		return nil, errors.New("srp: invalid SRP_B")
	}
	if new(big.Int).Mod(B, bigN).Sign() == 0 {
		return nil, errors.New("srp: invalid SRP_B (B mod N == 0)")
	}
	key, err := c.passwordKey(ch.UserIDForSRP, B, ch.SaltHex)
	if err != nil {
		return nil, err
	}
	block, err := base64.StdEncoding.DecodeString(ch.SecretBlock)
	if err != nil {
		return nil, fmt.Errorf("srp: invalid SECRET_BLOCK: %w", err)
	}
	ts := now.UTC().Format(TimestampLayout)
	sig := Signature(key, c.PoolID, ch.UserIDForSRP, block, ts)
	user := ch.Username
	if user == "" {
		user = ch.UserIDForSRP
	}
	return map[string]string{
		"TIMESTAMP":                   ts,
		"USERNAME":                    user,
		"PASSWORD_CLAIM_SECRET_BLOCK": ch.SecretBlock,
		"PASSWORD_CLAIM_SIGNATURE":    sig,
	}, nil
}

func (c *Client) passwordKey(userID string, B *big.Int, saltHex string) ([]byte, error) {
	u := calculateU(c.A, B)
	if u.Sign() == 0 {
		return nil, errors.New("srp: u cannot be zero")
	}
	x := calculateX(c.PoolID, userID, c.Password, saltHex)
	gx := new(big.Int).Exp(bigG, x, bigN)
	base := new(big.Int).Sub(B, new(big.Int).Mul(bigK, gx))
	base.Mod(base, bigN)
	exp := new(big.Int).Add(c.a, new(big.Int).Mul(u, x))
	s := new(big.Int).Exp(base, exp, bigN)
	return deriveKey(s, u), nil
}

func deriveKey(s, u *big.Int) []byte {
	sb, _ := hex.DecodeString(padInt(s))
	ub, _ := hex.DecodeString(padInt(u))
	return computeHKDF(sb, ub)
}

// Signature computes PASSWORD_CLAIM_SIGNATURE.
func Signature(key []byte, poolID, userID string, secretBlock []byte, timestamp string) string {
	m := hmac.New(sha256.New, key)
	m.Write([]byte(poolName(poolID)))
	m.Write([]byte(userID))
	m.Write(secretBlock)
	m.Write([]byte(timestamp))
	return base64.StdEncoding.EncodeToString(m.Sum(nil))
}

// --- Server side (for fakes) ---------------------------------------------

// Verifier returns v = g^x mod N for a user.
func Verifier(poolID, userID, password, saltHex string) *big.Int {
	return new(big.Int).Exp(bigG, calculateX(poolID, userID, password, saltHex), bigN)
}

// ServerB returns B = (k*v + g^b) mod N.
func ServerB(v, b *big.Int) *big.Int {
	B := new(big.Int).Mul(bigK, v)
	B.Add(B, new(big.Int).Exp(bigG, b, bigN))
	return B.Mod(B, bigN)
}

// ServerKey derives the shared HKDF key on the server side:
// S = (A * v^u)^b mod N.
func ServerKey(AHex string, v, b, B *big.Int) ([]byte, error) {
	A, ok := new(big.Int).SetString(AHex, 16)
	if !ok || new(big.Int).Mod(A, bigN).Sign() == 0 {
		return nil, errors.New("srp: invalid SRP_A")
	}
	u := calculateU(A, B)
	s := new(big.Int).Exp(v, u, bigN)
	s.Mul(s, A).Mod(s, bigN)
	s.Exp(s, b, bigN)
	return deriveKey(s, u), nil
}
